const fmt = (n) => "₹" + Number(n).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pct = (n) => (n >= 0 ? "+" : "") + n.toFixed(2) + "%";
const fmtDateLong = (d) => { if (!d) return null; const dt = new Date(d);
  return `${String(dt.getUTCDate()).padStart(2,"0")} ${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][dt.getUTCMonth()]} ${dt.getUTCFullYear()}`; };
const fmtDate = (d) => { if (!d) return "—"; const dt = new Date(d); const dd = String(dt.getUTCDate()).padStart(2,"0"); const mm = String(dt.getUTCMonth()+1).padStart(2,"0"); return `${dd}/${mm}/${dt.getUTCFullYear()}`; };
// Unlike fmtDate above (a plain DATE column, read as UTC to dodge a timezone shift), this is a
// real TIMESTAMPTZ with a time-of-day that actually needs converting — India has one timezone,
// UTC+5:30, no DST, so the offset is fixed rather than pulled from Intl.
const fmtDateTimeIST = (d) => { if (!d) return "—";
  const dt = new Date(new Date(d).getTime() + 5.5 * 3600 * 1000);
  const dd = String(dt.getUTCDate()).padStart(2, "0"), mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
  let h = dt.getUTCHours(); const ampm = h >= 12 ? "pm" : "am"; h = h % 12 || 12;
  const mi = String(dt.getUTCMinutes()).padStart(2, "0");
  return `${dd}/${mm}/${dt.getUTCFullYear()}, ${h}:${mi} ${ampm} IST`; };

// Catmull-Rom → cubic bezier: every line chart's points, drawn as one smooth curve instead of
// straight polyline segments. Control points sit at ±(next − prev)/6 either side of each point.
function smoothPathFromPoints(P) {
  let d = `M${P[0][0].toFixed(1)} ${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || P[i + 1];
    d += ` C${(p1[0] + (p2[0] - p0[0]) / 6).toFixed(1)} ${(p1[1] + (p2[1] - p0[1]) / 6).toFixed(1)}`
       + `,${(p2[0] - (p3[0] - p1[0]) / 6).toFixed(1)} ${(p2[1] - (p3[1] - p1[1]) / 6).toFixed(1)}`
       + `,${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
  }
  return d;
}
function smoothPath(vals, w, h, pad, mn, sp) {
  const P = vals.map((v, i) => [(i / (vals.length - 1)) * w, h - pad - ((v - mn) / sp) * (h - pad * 2)]);
  return { d: smoothPathFromPoints(P), points: P };
}

const Badge = ({ children, color }) => {
  const colors = { green: ["var(--good-soft)","#0B7A55"], blue: ["var(--accent-soft)","#4335C9"], amber: ["var(--warn-soft)","var(--warn)"], red: ["var(--bad-soft)","#C2353A"], violet: ["var(--invest-soft)","var(--invest)"], gray: ["var(--row-rule)","var(--ink-2)"] };
  const [bg, fg] = colors[color] || colors.gray;
  return <span style={{ background: bg, color: fg, padding: "2px 8px", borderRadius: 9999, fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>{children}</span>;
};

const INDEX_LABELS = { nifty50: "Nifty 50", sensex: "BSE Sensex", midcap150: "Nifty Midcap 150", smallcap250: "Nifty Smallcap 250", blend403030: "40/30/30 Blend" };
// Clients compare against the broad market only; cap-tier indices are an advisor tool.
const CLIENT_INDEXES = ["nifty50", "sensex"];

// Symbol chip tints — background / foreground, picked deterministically per symbol.
const SYMBOL_TINTS = [
  ["#EFF6FF", "#1D4ED8"], ["#ECFEFF", "#0E7490"], ["#ECFDF5", "#047857"], ["#FFF7ED", "#C2410C"],
  ["#FDF2F8", "#BE185D"], ["#F5F3FF", "#6D28D9"], ["#F1F5F9", "#334155"], ["#FEF2F2", "#B91C1C"],
];
const tintFor = (s = "") => SYMBOL_TINTS[((s.charCodeAt(0) || 0) + s.length) % 8];

// Logo files live in public/logos/ and the map is generated by scripts_harvest_logos.py.

// Rounded-square badge, per-symbol tint instead of a plain white tile — many of the harvested
// logos are transparent cutouts drawn in dark ink for a light background, so the tint (not a
// dark fill) is what keeps every one of them legible while still losing the white-box look.
const LogoChip = ({ symbol, size = 46 }) => {
  const src = SYMBOL_LOGOS[symbol];
  const [bg, fg] = tintFor(symbol);
  const base = {
    width: size, height: size, borderRadius: size * 0.3, boxSizing: "border-box",
    display: "flex", alignItems: "center", justifyContent: "center", flex: "none", background: bg,
  };
  if (!src) return (
    <div style={{ ...base, color: fg, fontSize: size * 0.28, fontWeight: 800, letterSpacing: ".02em" }}>
      {symbol.slice(0, 3)}
    </div>
  );
  return (
    <div style={{ ...base, padding: size * 0.12, overflow: "hidden" }}>
      <img src={src} alt={symbol} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain", display: "block" }} />
    </div>
  );
};

