// Stat tile: micro label · semibold value (proportional figures) · optional delta line.
// A 2px rail carries direction so the value is never colour-alone.
// `accent` colours the direction rail only. `tone` colours the value, and is used
// ONLY where the value itself is the good/bad signal (P&L, your own return) — an
// index's return is neutral information, so its card leaves the value in ink and
// lets the delta line carry direction.
// `size` bumps the figure when fewer cards share a row. `hypothetical` switches the
// shell to a dashed, shadowless surface so a counterfactual never reads as real money.
const Card = ({ title, value, sub, accent, tone, size = 29, hypothetical }) => (
  <div className={hypothetical ? "" : "card-hover"} style={{
    ...PANEL, padding: "18px 20px 16px",
    ...(hypothetical ? { background: "var(--surface-2)", border: "1px dashed #D3D6E2", boxShadow: "none" } : {}),
  }}>
    <span style={{ display: "block", width: 44, height: 4, borderRadius: 99, background: accent || "var(--ink-3)" }} />
    <div style={{ fontSize: 11, color: "#64748B", fontWeight: 700, textTransform: "uppercase", letterSpacing: ".08em", marginTop: 12 }}>{title}</div>
    <div className="fig" style={{ fontSize: size, lineHeight: 1.15, fontWeight: 800, color: tone || "var(--ink)", marginTop: 8, letterSpacing: "-.04em" }}>{value}</div>
    {sub && <div style={{ fontSize: 11.5, color: "var(--ink-3)", marginTop: 6, lineHeight: 1.35 }}>{sub}</div>}
  </div>
);

// ── Mobile shell ─────────────────────────────────────────────────────────────
// Inline styles can't carry media queries, so the breakpoint is read in JS and the
// mobile tree is a separate render branch off the same state.
const MOBILE_Q = "(max-width: 767px)";
function useIsMobile() {
  const [mobile, setMobile] = useState(() => typeof window !== "undefined" && window.matchMedia(MOBILE_Q).matches);
  useEffect(() => {
    const mq = window.matchMedia(MOBILE_Q);
    const onChange = (e) => setMobile(e.matches);
    setMobile(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return mobile;
}

